/* Additive Equity Lab UI and progress integration. Existing mode IDs stay stable. */
const equityFilters=['Count the Outs','Estimate Equity','Decide the Call','All Drills'];
function equitySetup(){if(!equityFilters.includes(filters.choice))filters.choice='All Drills';shell(`<div class="page"><button class="back" data-go="home">${svgIcon('back')} All practice modes</button><div class="eyebrow">Deliberate practice</div><h1>Equity Lab</h1><p class="muted">Your draw, your number. Estimate equity the way you will at the table: outs, then the rule of 2 and 4.</p><div class="choices">${equityFilters.map(o=>`<button data-choice="${o}" class="${filters.choice===o?'selected':''}">${o}</button>`).join('')}</div><div class="panel"><h3>${settings.length==='endless'?'An open-ended practice session':settings.length+' hands. One decision at a time.'}</h3><p class="muted">${modeLabel()} · 100bb · No rake</p>${tableSwitch()}<p class="muted">Count clean outs: cards that complete the named draw and put you ahead of the shown villain hand. Exclude cards that give villain a stronger hand. Overcards and pair improvements are not draw outs. Exact equity includes every showdown outcome against the shown hand.</p><button class="primary start" data-start>Start practice ${svgIcon('next')}</button></div><p class="source">Exact math · enumerated runouts · rule of 2 and 4</p></div>`)}
let equityRotation=null;
const equityRotationKey='gtoTrainer.equityRotation.v1';
function equitySpot(){
 if(filters.choice==='Decide the Call'||(filters.choice==='All Drills'&&Math.random()<3/EquityMath.scenarios.length)){let available=EquityMath.scenarios.filter(s=>s.drill==='Decide the Call'),unused=available.filter(s=>!session.used.has(s.id));return structuredClone(rand(unused.length?unused:available))}
 if(!equityRotation){let state=null;try{state=JSON.parse(localStorage.getItem(equityRotationKey))}catch{}equityRotation=EquityMath.createRotation({state})}
 const drill=filters.choice==='All Drills'?rand(['Count the Outs','Estimate Equity']):filters.choice;
 const spot=equityRotation.next(drill);try{localStorage.setItem(equityRotationKey,JSON.stringify(equityRotation.snapshot()))}catch{}return spot;
}

function faceText(c){return c[0]+({s:'♠',h:'♥',d:'♦',c:'♣'}[c[1]])}
const eqPercent=n=>n.toFixed(1)+'%';
function equityFigures(s,f){const m=s.math;return `<div class="equity-figures">${f.pick.estimate!==undefined?`<div><span>Your estimate</span><strong>${eqPercent(f.pick.estimate)}</strong></div>`:''}<div><span>Rule of 2/4</span><strong>${m.rule}%</strong></div><div><span>Exact (enumerated)</span><strong>${eqPercent(m.equity)}</strong></div>${f.required!==undefined?`<div><span>Pot odds required</span><strong>${eqPercent(f.required)}</strong></div>`:''}</div>`}
function equityFeedback(s,f){let m=EquityMath.refresh(s);return `<div class="verdict ${f.score===0?'bad':''}"><strong>${f.verdict}</strong><span class="grade">${f.score} / 1 point</span></div>${s.drill==='Count the Outs'?`<p>Your count: ${f.pick.outs} · Clean outs: <strong>${m.count}</strong></p>`:''}<p><strong>${m.count} clean outs:</strong> ${m.outs.map(faceText).join(' ')}.</p>${m.excluded.length?`<div class="dirty-outs"><strong>Not a clean out</strong>${m.excluded.map(x=>`<p><span class="excluded-card">${faceText(x.card)}</span> completes your draw but ${x.tie?'only ties the shown hand':`gives villain ${x.villainHand}`}. Excluded from the count.</p>`).join('')}</div>`:''}<p>Clean outs put you ahead on the next card. On the flop, villain can still redraw on the river. Overcards and pair improvements are excluded.</p>${equityFigures(s,f)}<p>${m.count} × ${m.multiplier} = ${m.rule}% (${m.multiplier===4?'flop · two cards to come':'turn · one card to come'}).</p>${m.multiplier===4&&m.count>=9?`<p>The raw rule of 4 drifts high at nine or more outs. Common adjustment: ${m.count} × 4 − (${m.count} − 8) = <strong>${m.adjusted}%</strong>. The drill grades the raw ${m.rule}% estimate.</p>`:''}<p>Exact equity is ${(m.equity-m.rule)>=0?'higher':'lower'} by ${Math.abs(m.equity-m.rule).toFixed(1)} points: it counts every showdown result, including pair improvements, backdoors, redraws, and ties; the shortcut estimates from your clean outs.</p>${s.drill==='Decide the Call'?`<p>${f.borderline?'Borderline: the rule and the exact number disagree here. Either Call or Fold earns full decision credit.':`Exact equity ${m.equity>=f.required?'meets':'is below'} the ${eqPercent(f.required)} price: ${f.exactAction}.`} Your decision: ${f.pick.decision}.</p><p>Estimate: ${f.estimateScore} / 1 · Decision: ${f.decisionScore} / 1. Each step contributes half the total score.</p>`:''}<p class="source">${m.runouts} ${s.board.length===3?'two-card runouts':'rivers'} · ${m.wins} wins · ${m.ties} ties · ${m.losses} losses · ties count as half a win.</p><div class="source">Exact math · enumerated runouts · rule of 2 and 4 · ${s.tableSize||settings.tableSize}-handed</div>`}
function renderEquity(){const s=session.current;EquityMath.refresh(s);const fb=session.feedback,deal=lastDealtSpot!==s;lastDealtSpot=s;if(deal)session.equityDraft='';let count=s.drill==='Count the Outs';app.innerHTML=`<main class="session equity-session ${deal?'deal':''} ${fb?'answered':''}"><div class="session-head"><button data-quit>${svgIcon('back')} Save & quit</button><span>Equity Lab · ${modeLabel()}</span>${tableSwitch()}<span>Hand ${session.index+1} / ${session.total===Infinity?'∞':session.total}</span></div><div class="progress-track"><i style="width:${session.total===Infinity?((session.index%10)+1)*10:session.index/session.total*100}%"></i></div><h2 class="session-title">${s.drill}</h2><p class="session-label">${s.board.length===3?'Flop · two cards to come':'Turn · one card to come'} · 100bb · No rake</p><div class="equity-felt"><div class="equity-hands"><div><span class="source">YOU</span><div class="hero-hand">${s.cards.map(card).join('')}</div></div><div><span class="source">VILLAIN · ${s.villainMade}</span><div class="villain-hand">${s.villainCards.map(card).join('')}</div></div></div><div class="board">${s.board.map(card).join('')}</div>${s.bet?`<p class="equity-pot">Pot ${s.pot}bb · Bet ${s.bet}bb</p>`:''}</div><p class="equity-prompt">Count <strong>clean outs</strong> for your <strong>${s.draw.toLowerCase()}</strong>: cards that complete the draw and put you ahead of villain. Exclude overcards and pair improvements.${count?'':` Given: <strong>${s.math.count} clean outs</strong>.`}</p><div class="feedback ${fb?'revealed':''}" aria-live="polite">${fb?equityFeedback(s,fb):`<p class="waiting">${count?'How many draw-completing cards put you ahead of the shown hand?':s.drill==='Estimate Equity'?'Use the given clean-out count to enter your equity estimate.':`Use the rule of ${s.math.multiplier}: ${s.math.count} outs × ${s.math.multiplier}.`}</p>`}</div><div class="action-zone">${fb?`<button class="primary equity-next" data-next><span>${session.index+1>=session.total?'See results':'Next hand'}</span>${svgIcon('next')}</button>`:`<form id="equity-form"><label for="equity-number">${count?'Clean outs':'Your equity estimate (%)'}</label><div class="equity-entry"><input id="equity-number" name="equityNumber" type="number" inputmode="${count?'numeric':'decimal'}" min="0" max="${count?47:100}" step="${count?1:'0.1'}" required autocomplete="off" aria-describedby="equity-input-help" value="${session.equityDraft??''}">${s.drill==='Decide the Call'?'<div class="equity-decisions"><button type="submit" name="decision" value="Fold">Fold <small>F</small></button><button class="primary" type="submit" name="decision" value="Call">Call <small>C</small></button></div>':'<button class="primary" type="submit">Check answer</button>'}</div><p id="equity-input-help" class="source">${count?'Enter a whole-number count.':s.drill==='Decide the Call'?'Enter your estimate, then choose Call or Fold.':'Enter your own equity estimate from 0 to 100%.'}</p></form>`}</div></main>`;const form=$('#equity-form');if(form){form.addEventListener('submit',e=>{e.preventDefault();submitEquity(e.submitter?.value)});$('#equity-number').addEventListener('input',e=>{session.equityDraft=e.target.value});$('#equity-number').addEventListener('keydown',e=>{if(s.drill==='Decide the Call'&&['f','c'].includes(e.key.toLowerCase())){e.preventDefault();submitEquity(e.key.toLowerCase()==='c'?'Call':'Fold')}})}}
function submitEquity(decision){if(!session||session.feedback||session.current.kind!=='equity')return;const input=$('#equity-number');if(!input||!input.reportValidity())return;const s=session.current,n=Number(input.value);if(s.drill==='Decide the Call'&&!['Call','Fold'].includes(decision))return;const pick=s.drill==='Count the Outs'?{outs:n}:{estimate:n,...(s.drill==='Decide the Call'?{decision}:{})};session.feedback=EquityMath.grade(s,pick);record(s,session.feedback);feedbackBlip(session.feedback.score);renderEquity()}
function recordEquity(s,f){const row={at:Date.now(),tableSize:s.tableSize||settings.tableSize,stackBb:100,rake:0,source:'Exact enumeration',kind:'equity',position:s.hero,spot:'Equity Lab',mode:'Equity Lab',score:f.score,hand:s.id,drill:s.drill};progress.push(row);write('progress',progress);session.answers.push(row);let m=mistakes.find(m=>m.id===(session.reviewId||s.id));if(m){m.spot=structuredClone(s);m.correctAnswer={outs:s.math.count,rule:s.math.rule}}if(f.score<1){if(!m){m={id:s.id,spot:structuredClone(s),wrongPick:f.pick,correctAnswer:{outs:s.math.count,rule:s.math.rule},consecutive:0,stage:0,due:Date.now(),misses:0,tag:'Equity Lab'};mistakes.push(m)}m.consecutive=0;m.stage=session.reviewId?Math.min((m.stage||0)+1,3):0;m.misses++;m.due=Date.now()+[0,1,3,7][m.stage]*86400000;m.wrongPick=f.pick;}else if(m&&session.reviewId){m.consecutive++;m.stage=Math.min((m.stage||0)+1,3);if(m.consecutive>=2)mistakes=mistakes.filter(x=>x.id!==m.id);else m.due=Date.now()+[0,1,3,7][m.stage]*86400000}write('mistakes',mistakes)}
function feedbackBlip(score){if(!settings.sound)return;try{const ac=new AudioContext(),osc=ac.createOscillator(),gain=ac.createGain();osc.type='square';osc.connect(gain);gain.connect(ac.destination);gain.gain.setValueAtTime(.015,ac.currentTime);gain.gain.setValueAtTime(.015,ac.currentTime+.11);gain.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.17);osc.frequency.setValueAtTime(score>0?440:440,ac.currentTime);osc.frequency.setValueAtTime(score>0?660:220,ac.currentTime+.075);osc.start();osc.stop(ac.currentTime+.18);osc.onended=()=>ac.close()}catch{}}
function xpDisplay(){const n=progress.length,into=n%250,level=Math.floor(n/250)+1;return `<section class="panel xp-panel"><div class="stats-row"><span>Level ${level}</span><span>${n} XP · ${250-into} to Level ${level+1}</span></div><div class="xp-bar" role="progressbar" aria-label="XP toward next level" aria-valuemin="0" aria-valuemax="250" aria-valuenow="${into}">${Array.from({length:25},(_,i)=>`<i class="${i*10<into?'earned':''}"></i>`).join('')}</div><p class="source">1 decision = 1 XP · a new level every 250 decisions</p></section>`}
function equitySelfCheck(){const flop=EquityMath.scenarios[0].math,turn=EquityMath.scenarios.find(s=>s.board.length===4).math;return `<details class="panel"><summary class="check-good">✓ Equity Lab enumeration check</summary><div class="stats-row"><span>Flop · 45 remaining cards</span><span>${flop.runouts} two-card runouts</span></div><div class="stats-row"><span>Turn · 44 remaining cards</span><span>${turn.runouts} rivers</span></div><p class="source">Known cards exclude both shown hands and the board. 45 × 44 ÷ 2 = 990; ties count as half a win.</p></details>`}
